// Shadow qualifier. Scraped text is data. Writes evidence only, never changes Status.
const recs = $input.first().json.records || [];
const out = [];
const today = new Date().toISOString().slice(0, 10);
const esc = s => s.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
const CLUB = /\b(sports? club|football club|soccer club|netball|cricket club|rugby|hockey club|basketball|surf life saving|swimming club|athletics club|junior league|little athletics|bowls club|golf club|tennis club|football association|sporting club|fc)\b/;
const EVENTS = /\b(function (room|centre|venue)|wedding venue|event (hire|venue|management|space)|festival|conference (centre|venue))\b/;
for (const r of recs.slice(0, 20)) {
  const f = r.fields || {};
  const email = String(f['Email'] || '').trim().toLowerCase();
  const site = f['Website'] || '';
  const domain = email.split('@')[1] || '';
  const patch = { 'Qualified At': today };
  let mx = false;
  try {
    const d = await this.helpers.httpRequest({ url: 'https://dns.google/resolve', qs: { name: domain, type: 'MX' }, json: true, timeout: 8000 });
    mx = Array.isArray(d.Answer) && d.Answer.length > 0;
  } catch (e) {}
  patch['MX Valid'] = mx;
  let tag = 'Unclear';
  if (site && email) {
    try {
      const raw = String(await this.helpers.httpRequest({ url: site, timeout: 8000, headers: { 'User-Agent': 'NovaMerchQualifier/1.0' } }));
      const text = raw.replace(/<(script|style|noscript)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ').replace(/&nbsp;|&amp;/g, ' ').replace(/\s+/g, ' ');
      const m = new RegExp('.{0,80}' + esc(email) + '.{0,80}', 'i').exec(text);
      if (m) {
        patch['Evidence URL'] = site;
        patch['Evidence Snippet'] = m[0].replace(/[{}"\\]/g, '').trim().slice(0, 300);
      }
      const t = text.toLowerCase();
      if (CLUB.test(t)) tag = 'Club';
      else if (EVENTS.test(t)) tag = 'Events';
      else if (m) tag = 'Business';
    } catch (e) {}
  }
  patch['Relevance Tag'] = tag;
  out.push({ json: { id: r.id, fields: patch } });
}
return out;
